local is_configured = false

return {
    setup = function()
        if is_configured then
            return
        end

        local success, bte = pcall(require, "ts-error-translator")
        if not success then
            vim.notify(
                "`ts-error-translator` is either not installed or not available.",
                vim.log.levels.ERROR
            )
            return
        end

        bte.setup({
            auto_attach = true,
            servers = {
                "astro-language-server",
                "vtsls",
            },
        })

        is_configured = true
    end,
}
